using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key-here";
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

// --- Tools ---
var notes = new ResearchNotes();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(
            (string query) => WebSearchTool.SearchAsync(query),
            "web_search",
            "Searches the web for information. Returns a list of relevant snippets."),
        AIFunctionFactory.Create(
            ([Description("The note text to save")] string note) => notes.AddNote(note),
            "save_note",
            "Saves an important finding as a note for later reference."),
        AIFunctionFactory.Create(
            () => notes.GetAllNotes(),
            "get_notes",
            "Retrieves all saved research notes.")
    ]
};

// --- Build the chat client with automatic tool invocation ---
IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// --- Agent system prompt ---
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research the given topic thoroughly.

        Follow this process:
        1. Search the web for information about the topic (make 2-3 searches with different queries).
        2. Save important findings as notes using the save_note tool.
        3. After gathering enough information, retrieve your notes and produce a final summary.

        Your final response should be a well-structured summary of your research findings.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

Console.WriteLine($"\nResearching: {topic}\n");
Console.WriteLine("Agent is working...\n");

// --- Run the agent loop ---
var response = await client.GetChatResponseAsync(messages, chatOptions);

Console.WriteLine("=== Research Summary ===\n");
Console.WriteLine(response.Text);
Console.WriteLine($"\n=== Notes Collected: {notes.Count} ===");
foreach (var note in notes.AllNotes)
{
    Console.WriteLine($"  • {note}");
}

// --- Tool implementations ---

/// <summary>Simulated web search tool that returns results for a query.</summary>
static class WebSearchTool
{
    private static readonly HttpClient Http = new();

    public static async Task<string> SearchAsync(string query)
    {
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");

        // Use a public search API (DuckDuckGo Instant Answer)
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await Http.GetStringAsync(url);

            // Extract the abstract and related topics from the response
            using var doc = System.Text.Json.JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            var abstractText = root.GetProperty("Abstract").GetString();
            if (!string.IsNullOrEmpty(abstractText))
                results.Add($"Summary: {abstractText}");

            var abstractSource = root.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrEmpty(abstractSource))
                results.Add($"Source: {abstractSource}");

            if (root.TryGetProperty("RelatedTopics", out var related))
            {
                foreach (var item in related.EnumerateArray().Take(5))
                {
                    if (item.TryGetProperty("Text", out var text))
                        results.Add($"- {text.GetString()}");
                }
            }

            return results.Count > 0
                ? string.Join("\n", results)
                : $"No detailed results found for '{query}'. Try a more specific search.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }
}

/// <summary>Note-taking tool for storing research findings.</summary>
class ResearchNotes
{
    private readonly List<string> _notes = [];

    public int Count => _notes.Count;
    public IReadOnlyList<string> AllNotes => _notes;

    public string AddNote(string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note saved ({_notes.Count} total)");
        return $"Note saved successfully. You now have {_notes.Count} note(s).";
    }

    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        Console.WriteLine($"  [Tool] Retrieving {_notes.Count} notes");
        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

