+/// <summary>Simulated web search tool that returns results for a query.</summary>
+static class WebSearchTool
+{
+    private static readonly HttpClient Http = new();
+
+    public static async Task<string> SearchAsync(string query)
+    {
+        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");
+
+        // Use a public search API (DuckDuckGo Instant Answer)
+        try
+        {
+            var encoded = Uri.EscapeDataString(query);
+            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
+            var json = await Http.GetStringAsync(url);
+
+            // Extract the abstract and related topics from the response
+            using var doc = System.Text.Json.JsonDocument.Parse(json);
+            var root = doc.RootElement;
+
+            var results = new List<string>();
+
+            var abstractText = root.GetProperty("Abstract").GetString();
+            if (!string.IsNullOrEmpty(abstractText))
+                results.Add($"Summary: {abstractText}");
+
+            var abstractSource = root.GetProperty("AbstractSource").GetString();
+            if (!string.IsNullOrEmpty(abstractSource))
+                results.Add($"Source: {abstractSource}");
+
+            if (root.TryGetProperty("RelatedTopics", out var related))
+            {
+                foreach (var item in related.EnumerateArray().Take(5))
+                {
+                    if (item.TryGetProperty("Text", out var text))
+                        results.Add($"- {text.GetString()}");
+                }
+            }
+
+            return results.Count > 0
+                ? string.Join("\n", results)
+                : $"No detailed results found for '{query}'. Try a more specific search.";
+        }
+        catch (Exception ex)
+        {
+            return $"Search failed: {ex.Message}. Try a different query.";
+        }
+    }
+}
